const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lists;try{lists=JSON.parse(localStorage.getItem('wishlist-v1'));if(!Array.isArray(lists)||!lists.length)throw 0;lists=lists.filter(l=>typeof l.name==='string'&&Array.isArray(l.items));if(!lists.length)throw 0}catch{lists=[{name:'My birthday',items:[]},{name:'Christmas wishes',items:[]}]}
let category='All finds',recipient='all',trend='all',visibleCount=48,lastFilterKey='',activeList=0,toastTimer;const categories=['All finds','Tech & gaming','Style & accessories','Self-care','Home & cozy','Sport & outdoors','Creative corner'],icons=['✳','◉','✧','♡','⌂','☀','✎'];

const trendEdits={
 cafe:{title:'Café at home',icon:'☕',metric:'54.4K posts',label:'#cafeathome · TikTok 2026 report',reason:'TikTok’s 2026 report highlights making café-style drinks at home. These are our related coffee and tea picks.',source:'https://ads.tiktok.com/business/en-US/next'},
 creator:{title:'Creator corner',icon:'♫',metric:'+115% search growth',label:'Podcast microphones · Google, 2026',reason:'Google reports rising U.S. search interest in podcast microphones. Microphones and complementary desk gear are editorial picks for this interest.',source:'https://blog.google/products-and-platforms/products/shopping/holiday-100-gift-guide-2026/'},
 offline:{title:'Make something',icon:'✂',metric:'30% of consumers',label:'Creative hobbies for recharge · Circana, 2026',reason:'Circana reports interest in hobbies and creative activities. We selected journals, craft kits, and other screen-free ideas to match.',source:'https://www.circana.com/post/consumer-wellness-trends-insights-from-circana-s-wellbeing-report'},
 scent:{title:'Signature scent',icon:'✧',metric:'Top gift-set type',label:'Perfume searches · Google, 2026',reason:'Google names perfume as the most searched type of gift set in 2026. Fragrances and complementary home scents are our editorial selections.',source:'https://blog.google/products-and-platforms/products/shopping/holiday-100-gift-guide-2026/'},
 reset:{title:'The routine reset',icon:'♡',metric:'#hygiene',label:'Self-care signal · TikTok Next 2026',reason:'TikTok’s 2026 report identifies everyday self-care routines as a theme. The collection includes editorial hair-care and routine essentials.',source:'https://ads.tiktok.com/business/en-US/next'},
 hydration:{title:'Hydration station',icon:'◒',metric:'45% of adults',label:'Trying to drink more water · Circana, 2026',reason:'Circana reports adults’ interest in drinking more water. These bottles and tumblers are curated options for that everyday interest.',source:'https://www.circana.com/post/consumer-wellness-trends-insights-from-circana-s-wellbeing-report'}
};
function editKeys(p){const text=(p.name+' '+p.brand).toLowerCase(),keys=[];
 if(/coffee|espresso|kettle|barista|matcha|tea set|tea concentrate|carter|aeropress|carafe|brewer/.test(text))keys.push('cafe');
 if(p.category==='Tech & gaming'&&/microphone|keyboard|mouse|headset|mixer|desk|stand|charger/.test(text))keys.push('creator');
 if(p.category==='Creative corner'&&!/toniebox|tonies|tonieplay/.test(text))keys.push('offline');
 if(/perfume|fragrance|candle|incense|diffuser|glow oil/.test(text))keys.push('scent');
 if(p.category==='Self-care'&&!keys.includes('scent'))keys.push('reset');
 if(/owala|stanley/.test(p.brand.toLowerCase())&&/freesip|bottle|quencher|iceflow|tumbler/.test(text)&&!/key chain|ornament|straws|gasket/.test(text))keys.push('hydration');
 return keys;}
products.forEach(p=>{p.editKeys=editKeys(p);p.trendPriority=p.editKeys.length+(p.id>=1062?3:0)+(p.brand==='Cécred'||p.brand==='FIFINE'?2:0);});
const image=p=>p.image || `https://images.unsplash.com/photo-${photos[p.photo]}?w=650&auto=format&fit=crop&q=85`;
const isSaved=id=>lists.some(l=>l.items.includes(id));
function persist(){localStorage.setItem('wishlist-v1',JSON.stringify(lists));$('#navCount').textContent=new Set(lists.flatMap(l=>l.items)).size;render()}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function render(){ $('#categories').innerHTML=categories.map((c,i)=>`<button class="${c===category?'selected':''}" data-cat="${c}">${icons[i]} &nbsp;${c}</button>`).join('');const query=$('#search').value.toLowerCase();const filterKey=JSON.stringify([query,category,recipient,trend,$('#age').value,$('#budget').value,$('#brand').value,$('#sort').value]);if(filterKey!==lastFilterKey){visibleCount=48;lastFilterKey=filterKey;}document.querySelectorAll('.recipient-tabs [data-recipient]').forEach(b=>{const on=b.dataset.recipient===recipient;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on));});let shown=products.filter(p=>!p.legacy&&(trend==='all'||p.editKeys.includes(trend))&&(recipient==='all'||(p.recipients||['him','her']).includes(recipient))&&($('#brand').value==='all'||p.brand===$('#brand').value)&&(category==='All finds'||p.category===category)&&($('#age').value==='all'||p.ages.includes($('#age').value))&&($('#budget').value==='all'||p.price<Number($('#budget').value))&&`${p.name} ${p.brand} ${p.category}`.toLowerCase().includes(query));if($('#sort').value==='curated')shown=diversifyBrands(shown.sort((a,b)=>b.trendPriority-a.trendPriority));else shown.sort((a,b)=>$('#sort').value==='low'?a.price-b.price:b.price-a.price);$('#results').textContent=`${shown.length.toLocaleString()} finds to fall in love with`;$('#pageStatus').textContent=`Showing ${Math.min(visibleCount,shown.length).toLocaleString()} of ${shown.length.toLocaleString()} finds`;$('#loadMore').hidden=visibleCount>=shown.length;$('#grid').innerHTML=shown.length?shown.slice(0,visibleCount).map((p,i)=>`<article class="card"><div class="product-image" data-product="${p.id}" tabindex="0" role="button" aria-label="View ${esc(p.name)}" style="--bg:${['#fff3f8','#fff8fb','#fceaf2','#fff5f9'][i%4]}"><img src="${image(p)}" alt="${esc(p.name)}" loading="lazy">${p.badge?`<span class="badge">${p.badge}</span>`:''}<button class="heart ${isSaved(p.id)?'saved':''}" data-save="${p.id}" aria-label="Save ${esc(p.name)}" aria-pressed="${isSaved(p.id)}">${isSaved(p.id)?'♥':'♡'}</button></div><div class="brand">${esc(p.brand)}</div><h3 data-product="${p.id}" tabindex="0">${esc(p.name)}</h3><div class="card-bottom"><span class="price">~$${p.price}</span><span class="tag">${p.category}</span></div></article>`).join(''):'<div class="empty">No finds match just yet. Try another interest or budget.<br><button onclick="resetFilters()">Clear filters ↗</button></div>'}
function showProduct(id){const p=products[id];const d=$('#productDialog');d.innerHTML=`<button class="close" aria-label="Close">×</button><img class="detail-image" src="${image(p)}" alt="${esc(p.name)}"><div class="brand">${esc(p.brand)} · ${p.category}</div><h2 class="modal-title">${esc(p.name)}</h2><p class="modal-copy">${esc(p.description)}</p>${p.editKeys.length?`<div class="pick-reason"><strong>Why this edit</strong><p>${esc(trendEdits[p.editKeys[0]].reason)}</p><a href="${trendEdits[p.editKeys[0]].source}" target="_blank" rel="noopener noreferrer">Read the public trend source ↗</a></div>`:''}<strong>From / approx. $${p.price}</strong><p class="modal-copy">Product details checked November 12, 2026. Displayed prices are starting prices or budget estimates; size, shade, stock, and price can change. Confirm your selection at the official store.</p><div class="modal-controls"><select id="saveTo" aria-label="Choose wishlist">${lists.map((l,i)=>`<option value="${i}">${esc(l.name)}</option>`).join('')}</select><button class="primary" id="addItem">Add to wishlist ♡</button></div><a class="retailer" href="${p.url}" target="_blank" rel="noopener noreferrer">View product at ${esc(p.brand)} ↗</a>`;d.querySelector('.close').onclick=()=>d.close();$('#addItem').onclick=()=>{const l=lists[Number($('#saveTo').value)];if(l.items.includes(id)){toast('Already on this wishlist');return}l.items.push(id);persist();toast(`Added to ${l.name}`)};if(!d.open)d.showModal()}
function showLists(){const d=$('#listDialog');activeList=Math.min(activeList,lists.length-1);const l=lists[activeList];d.innerHTML=`<button class="close" aria-label="Close">×</button><div class="eyebrow">YOUR SOMEDAY THINGS</div><h2>My wishlists ♡</h2><p class="modal-copy">Saved on this browser. Export a list to share its shopping links.</p><div class="list-tabs">${lists.map((l,i)=>`<button data-list="${i}" class="${i===activeList?'selected':''}">${esc(l.name)} · ${l.items.length}</button>`).join('')}</div><form id="newList"><input required maxlength="60" placeholder="Name a new list, e.g. Birthday 2027" aria-label="New wishlist name"><button class="primary" type="submit">Create list +</button></form><h3>${esc(l.name)}</h3>${l.items.length?l.items.filter(id=>products[id]).map(id=>{const p=products[id];return `<div class="list-item"><img src="${image(p)}" alt=""><div><h3>${esc(p.name)}</h3><a href="${p.url}" target="_blank" rel="noopener noreferrer">Shop ${esc(p.brand)} ↗</a> <span class="tag">~$${p.price}</span></div><button data-remove="${id}" aria-label="Remove ${esc(p.name)}">×</button></div>`}).join(''):'<p class="modal-copy">Your next favorite belongs here. Explore the feed and tap a heart to start.</p>'}<div class="modal-controls"><button id="exportList" class="primary">Export list ↗</button><button id="deleteList">Delete this list</button></div>`;d.querySelector('.close').onclick=()=>d.close();d.querySelectorAll('[data-list]').forEach(b=>b.onclick=()=>{activeList=+b.dataset.list;showLists()});$('#newList').onsubmit=e=>{e.preventDefault();lists.push({name:e.target.querySelector('input').value.trim()||'My wishlist',items:[]});activeList=lists.length-1;persist();showLists()};d.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{l.items=l.items.filter(id=>id!==+b.dataset.remove);persist();showLists()});$('#deleteList').onclick=()=>{if(!confirm(`Delete “${l.name}”?`))return;lists.splice(activeList,1);if(!lists.length)lists.push({name:'My wishlist',items:[]});activeList=0;persist();showLists()};$('#exportList').onclick=()=>{const content=l.name+'\n\n'+l.items.filter(id=>products[id]).map(id=>{const p=products[id];return p.name+' — estimated $'+p.price+'\n'+p.url}).join('\n\n');const url=URL.createObjectURL(new Blob([content],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download=l.name.replace(/[^a-z0-9]/gi,'-')+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};if(!d.open)d.showModal()}
function resetFilters(){category='All finds';recipient='all';trend='all';$('#edit').value='all';$('#brand').value='all';$('#search').value='';$('#age').value='all';$('#budget').value='all';$('#sort').value='curated';render()}
$('#categories').onclick=e=>{const b=e.target.closest('[data-cat]');if(b){category=b.dataset.cat;render()}};$('#grid').onclick=e=>{const b=e.target.closest('[data-save]');if(b){showProduct(+b.dataset.save);return}const p=e.target.closest('[data-product]');if(p)showProduct(+p.dataset.product)};$('#grid').onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-product]')){e.preventDefault();showProduct(+e.target.dataset.product)}};['search','age','budget','sort','brand','edit'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',()=>{trend=$('#edit').value;render();}));['listsNav','profile','createBottom'].forEach(id=>$('#'+id).onclick=showLists);$('#discover').onclick=()=>$('#explore').scrollIntoView();$('#reset').onclick=()=>{resetFilters();$('#explore').scrollIntoView()};document.querySelectorAll('[data-occasion]').forEach(b=>b.onclick=()=>{const name=b.dataset.occasion;let i=lists.findIndex(l=>l.name.toLowerCase().includes(name.toLowerCase()));if(i<0){lists.push({name,items:[]});i=lists.length-1;persist()}activeList=i;showLists()});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));initializeCatalogControls();persist();

