const heroOne=document.querySelector('.p1 img'),heroTwo=document.querySelector('.p2 img');heroOne.src=image(products[20]);heroOne.alt='Owala FreeSip water bottle';heroTwo.src=image(products[23]);heroTwo.alt='rhode Pocket Blush in Sleepy Girl';

function initializeCatalogControls(){
 $('#catalogTotal').textContent=currentCatalog.length.toLocaleString();
 document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>jumpToEdit(b.dataset.edit));
 $('#edit').innerHTML='<option value="all">All trend edits</option>'+Object.entries(trendEdits).map(([key,t])=>`<option value="${key}">${t.title}</option>`).join('');

 const brands=[...new Set(currentCatalog.map(p=>p.brand))].sort();
 $('#brand').innerHTML='<option value="all">All brands</option>'+brands.map(b=>`<option value="${esc(b)}">${esc(b)}</option>`).join('');
 for(const who of ['him','her'])$('#'+who+'Count').textContent=currentCatalog.filter(p=>(p.recipients||['him','her']).includes(who)).length.toLocaleString()+' finds to explore';
 document.querySelectorAll('[data-recipient]').forEach(b=>b.addEventListener('click',()=>{recipient=b.dataset.recipient;render();if(!b.closest('.recipient-tabs'))$('#explore').scrollIntoView({behavior:'smooth'});}));
 $('#loadMore').onclick=()=>{visibleCount+=48;render();};
}

function jumpToEdit(key){resetFilters();trend=key==='adult'?'all':key;$('#edit').value=trend;if(key==='adult')$('#age').value='adults';render();$('#explore').scrollIntoView({behavior:'smooth'});}

function diversifyBrands(items){const groups=new Map();for(const p of items){if(!groups.has(p.brand))groups.set(p.brand,[]);groups.get(p.brand).push(p);}const out=[];for(let i=0;out.length<items.length;i++)for(const group of groups.values())if(group[i])out.push(group[i]);return out;}
